    {
      "claim": "The posterior distribution is a probability distribution over theta given observed data X₁,...,Xₙ",
      "supported": true,
      "evidence_or_problem": "Source: [00:33:37\u201300:34:13] 'we simply derive a posterior distribution, P of theta given X1, Xn'"
